insert into review_release_020_lessons values
  ('july-30-part-1', '2026-07-30', 'Hope, Wish & Real-Life Regrets — Part 1', 'hope / wish と現実・後悔 — Part 1', 'Choose hope for realistic future wishes, wish for a different present, and wish + had for past regrets.', '実現可能な未来のhope、今と違う願いのwish、過去の後悔を表すwish + hadを使い分けます。', '3c8fb48a-4617-815c-b642-f7b782ea654f', 'https://app.notion.com/p/3c8fb48a4617815cb642f7b782ea654f', 'part-1', null, 1, '{"bundled":true,"sourceSegment":"part-1","partIndex":1,"themes":["hope for the future","wish + past","wish + past perfect","could"],"phrases":[{"en":"I hope I can visit Malaysia next year.","jp":"来年マレーシアを訪れられるといいです。","topic":"hope","note":"実現可能な未来の願いには hope を使います。"},{"en":"I hope everything goes well.","jp":"すべてうまくいくといいですね。","topic":"hope","note":"hope の後ろには現在形でも未来の意味を表せます。"},{"en":"I wish I were in Malaysia now.","jp":"今マレーシアにいたらいいのに。","topic":"wish now","note":"今の現実と違う願いは wish + 過去形です。"},{"en":"I wish I had more free time.","jp":"もっと自由な時間があればいいのに。","topic":"wish now","note":"今は時間が少ない、という現実との違いを表します。"},{"en":"I wish I could speak English more confidently.","jp":"もっと自信を持って英語を話せたらいいのに。","topic":"wish + could","note":"今できない能力への願いは wish + could です。"},{"en":"I wish I had studied harder.","jp":"もっと一生懸命勉強しておけばよかった。","topic":"past regret","note":"過去への後悔は wish + had + 過去分詞です。"},{"en":"I wish I had gone with you.","jp":"あなたと一緒に行けばよかった。","topic":"past regret","note":"実際には行かなかった過去を振り返ります。"},{"en":"I wish I had called her earlier.","jp":"もっと早く彼女に電話すればよかった。","topic":"past regret","note":"had called で、しなかった過去への後悔を表します。"},{"en":"I wish I hadn’t said that.","jp":"あんなことを言わなければよかった。","topic":"past regret","note":"過去にしたことを後悔する否定形です。"},{"en":"I hope you feel better soon.","jp":"早く元気になるといいですね。","topic":"hope","note":"相手への現実的な願いにも hope を使います。"},{"en":"I wish the weather were cooler.","jp":"もっと涼しい天気ならいいのに。","topic":"wish now","note":"今の天気と反対の願いを表します。"},{"en":"I hope we can meet again.","jp":"また会えるといいですね。","topic":"hope","note":"可能性のある未来には hope + can が自然です。"}],"draft_questions":33}'::jsonb),
  ('july-30-part-2', '2026-07-30', 'Perfect Tenses on a Clear Timeline — Part 2', '完了形を時間の流れで整理 — Part 2', 'Place already, yet, just and past-perfect events on a clear timeline so the order of events stays easy to follow.', 'already・yet・justと過去完了を時間の流れで整理し、出来事の前後関係を分かりやすく伝えます。', '3c8fb48a-4617-815c-b642-f7b782ea654f', 'https://app.notion.com/p/3c8fb48a4617815cb642f7b782ea654f', 'part-2', null, 1, '{"bundled":true,"sourceSegment":"part-2","partIndex":2,"themes":["present perfect","past perfect","had vs had been","already"],"phrases":[{"en":"I have already eaten breakfast.","jp":"私はもう朝食を食べました。","topic":"present perfect","note":"already は通常 have と過去分詞の間に置きます。"},{"en":"I haven’t eaten dinner yet.","jp":"私はまだ夕食を食べていません。","topic":"present perfect","note":"yet は否定文では通常、文末に置きます。"},{"en":"I’ve just arrived home.","jp":"私はたった今家に着きました。","topic":"present perfect","note":"just は have と過去分詞の間です。"},{"en":"I have lived here since 2016.","jp":"私は2016年からここに住んでいます。","topic":"present perfect","note":"過去から今まで続く状態には現在完了を使います。"},{"en":"I had already eaten when you arrived.","jp":"あなたが着いた時には、私はもう食べ終えていました。","topic":"past perfect","note":"過去の二つの出来事のうち、先に起きた方を had + 過去分詞で表します。"},{"en":"She had left before I called.","jp":"私が電話する前に、彼女は出発していました。","topic":"past perfect","note":"before と過去完了で出来事の順番を明確にします。"},{"en":"He had finished the report by noon.","jp":"彼は正午までにレポートを終えていました。","topic":"past perfect","note":"by + 過去の時点は、その時までの完了を表します。"},{"en":"I had a car when I lived there.","jp":"そこに住んでいた時、私は車を持っていました。","topic":"had","note":"had は単純過去で「持っていた」です。"},{"en":"I had been there before.","jp":"私は以前そこへ行ったことがありました。","topic":"had been","note":"had been は、過去の基準時より前の経験です。"},{"en":"I wish I had been born there.","jp":"そこで生まれていたらよかったのに。","topic":"be born","note":"be born の過去完了は had been born です。"},{"en":"She had been tired before the meeting started.","jp":"会議が始まる前から彼女は疲れていました。","topic":"had been","note":"had been + 形容詞で、過去の基準時より前の状態を表せます。"},{"en":"Have you finished your work yet?","jp":"もう仕事を終えましたか？","topic":"present perfect","note":"今の時点で終わったかを尋ねる現在完了の質問です。"}],"draft_questions":33}'::jsonb),
  ('august-02', '2026-08-02', 'Polite Questions, Privacy & Clear Comparisons', '丁寧な質問・プライバシー・比較表現', 'Ask personal questions respectfully, protect privacy, tell similar things apart, and contrast ideas with despite and although.', '個人的な質問と断り方、似たものの見分け方、despiteとalthoughの比較表現を丁寧に練習します。', '3b0fb48a-4617-8029-bc0e-d6def0eea387', 'https://app.notion.com/p/3b0fb48a46178029bc0ed6def0eea387', 'full', null, 1, '{"bundled":true,"sourceSegment":"full","partIndex":0,"themes":["polite personal questions","pry into","tell apart","despite / although"],"phrases":[{"en":"Do you mind if I ask how old you are?","jp":"年齢を伺ってもよろしいですか？","topic":"polite questions","note":"個人的な質問の前に許可を求める丁寧な言い方です。"},{"en":"I’d rather not say.","jp":"できれば言いたくありません。","topic":"privacy","note":"答えたくない時の柔らかい断り方です。"},{"en":"I hope I didn’t offend you.","jp":"気を悪くさせていなければいいのですが。","topic":"apology","note":"offend は「気分を害する」です。"},{"en":"I don’t want to pry into your private life.","jp":"あなたの私生活に立ち入りたくありません。","topic":"pry into","note":"pry into は必要以上に詮索することです。"},{"en":"Let’s dig into the details.","jp":"詳しい内容を掘り下げましょう。","topic":"dig into","note":"dig into は話題や情報を詳しく調べる前向きな表現です。"},{"en":"I can’t tell the twins apart.","jp":"私はその双子を見分けられません。","topic":"tell apart","note":"似た二人・二つを区別する時に使います。"},{"en":"I recognized him from behind.","jp":"私は後ろ姿で彼だと分かりました。","topic":"recognize","note":"recognize は見覚え・聞き覚えから分かることです。"},{"en":"Can you identify the person in this photo?","jp":"この写真の人物を特定できますか？","topic":"identify","note":"identify は誰・何であるかを特定する表現です。"},{"en":"Despite the rain, we went out.","jp":"雨にもかかわらず、私たちは出かけました。","topic":"despite","note":"despite の後ろには名詞を置きます。"},{"en":"Although it was raining, we went out.","jp":"雨が降っていましたが、私たちは出かけました。","topic":"although","note":"although の後ろには主語 + 動詞の節を置きます。"},{"en":"Let me check my schedule and get back to you.","jp":"予定を確認して、またご連絡します。","topic":"schedule","note":"すぐに返事できない時の自然な仕事表現です。"},{"en":"I’ve told you a hundred times.","jp":"もう100回も言いました。","topic":"number of times","note":"回数は a hundred times のように表します。"}],"draft_questions":33}'::jsonb),
  ('august-03', '2026-08-03', 'Yet, Never & Everyday Experiences', 'yet / never と日常の経験', 'Talk naturally about what you have not done yet, experiences you have never had, finished past events and everyday habits.', 'まだしていないこと、未経験、終わった過去、日常の習慣を時制に合わせて自然に話します。', '3c7fb48a-4617-81da-b21f-dd973c1028e4', 'https://app.notion.com/p/3c7fb48a461781dab21fdd973c1028e4', 'full', null, 1, '{"bundled":true,"sourceSegment":"full","partIndex":0,"themes":["haven’t ... yet","didn’t","have never","acquired taste"],"phrases":[{"en":"I haven’t taken a bath yet.","jp":"私はまだお風呂に入っていません。","topic":"not yet","note":"今日など、まだ続いている時間には現在完了が自然です。"},{"en":"I didn’t take a bath last night.","jp":"私は昨夜お風呂に入りませんでした。","topic":"finished past","note":"last night のような終わった時には過去形を使います。"},{"en":"Have you taken a shower yet?","jp":"もうシャワーを浴びましたか？","topic":"not yet","note":"今までに済んだかを確認する質問です。"},{"en":"I have never tried that before.","jp":"私はそれを一度も試したことがありません。","topic":"never","note":"have never + 過去分詞で経験がないことを表します。"},{"en":"I tried it yesterday.","jp":"私は昨日それを試しました。","topic":"finished past","note":"yesterday があるため単純過去です。"},{"en":"Coffee can be an acquired taste.","jp":"コーヒーは慣れると好きになる味です。","topic":"acquired taste","note":"最初は苦手でも、経験とともに好きになる味です。"},{"en":"It has a sophisticated flavor.","jp":"それは洗練された味わいです。","topic":"flavor","note":"大人っぽく複雑な味を肯定的に表します。"},{"en":"This flavor is more popular with adults.","jp":"この味は大人により人気があります。","topic":"preferences","note":"「大人向け」に近い中立的な説明です。"},{"en":"I have already had lunch.","jp":"私はもう昼食を食べました。","topic":"already","note":"already は完了したことを強調します。"},{"en":"I haven’t decided yet.","jp":"私はまだ決めていません。","topic":"not yet","note":"未決定の状態が今も続いています。"},{"en":"She had left before I arrived.","jp":"私が着く前に、彼女は帰っていました。","topic":"past perfect","note":"先に起きた過去を過去完了で示します。"},{"en":"He plays tennis every weekend.","jp":"彼は毎週末テニスをします。","topic":"habit","note":"繰り返す習慣には現在形を使います。"}],"draft_questions":33}'::jsonb),
  ('august-09', '2026-08-09', 'Tears, Drinks & Countable Nouns', '涙・飲み物と数えられる名詞', 'Describe emotional reactions and order food or drinks with natural counters while distinguishing spill, pour, tear and tier.', '涙の表現、飲食物の自然な数え方、spill / pour・tear / tierの違いを会話で使える形にします。', '3c7fb48a-4617-8111-9092-fb5d18d0217c', 'https://app.notion.com/p/3c7fb48a461781119092fb5d18d0217c', 'full', null, 1, '{"bundled":true,"sourceSegment":"full","partIndex":0,"themes":["shed a tear","burst into tears","countable nouns","spill / pour"],"phrases":[{"en":"She shed a tear during the movie.","jp":"彼女は映画の途中で一筋の涙を流しました。","topic":"shed a tear","note":"shed の過去形も shed です。tear は「涙」です。"},{"en":"He burst into tears.","jp":"彼は突然泣き出しました。","topic":"burst into tears","note":"急に泣き始める強い変化を表します。"},{"en":"The story brought tears to my eyes.","jp":"その話を聞いて涙がこみ上げました。","topic":"tears","note":"感動などで自然に涙が出そうな時の表現です。"},{"en":"I need a glass of water.","jp":"コップ一杯の水が必要です。","topic":"uncountable nouns","note":"water は量の容器を使って数えます。"},{"en":"Could I have two coffees, please?","jp":"コーヒーを2杯いただけますか？","topic":"countable servings","note":"店では coffee が「一杯」の意味で数えられます。"},{"en":"We ordered a whole chicken.","jp":"私たちは丸ごとの鶏を一羽注文しました。","topic":"countable food","note":"動物・丸ごとの料理としては chicken を数えられます。"},{"en":"I had some chicken for lunch.","jp":"私は昼食に鶏肉を食べました。","topic":"uncountable food","note":"肉としての chicken は通常、数えません。"},{"en":"Would you like a piece of cake?","jp":"ケーキを一切れいかがですか？","topic":"portions","note":"cake を切り分けた量は a piece of で表します。"},{"en":"There’s a hair in my soup.","jp":"スープの中に髪の毛が一本あります。","topic":"countable hair","note":"一本の毛なら a hair と数えられます。"},{"en":"I spilled water on the table.","jp":"私はテーブルに水をこぼしました。","topic":"spill","note":"意図せず容器の外へ出た時は spill です。"},{"en":"Please pour the water into the glass.","jp":"水をコップに注いでください。","topic":"pour","note":"意図的に液体を注ぐ時は pour です。"},{"en":"This building has three tiers.","jp":"この建物には3つの層があります。","topic":"tear vs tier","note":"tier は「段・層」で、tear「涙」と発音が異なります。"}],"draft_questions":33}'::jsonb),
  ('august-10-part-1', '2026-08-10', 'Clear Calls & Kitchen Vocabulary — Part 1', '通話の聞き返しと台所の単語 — Part 1', 'Handle a poor phone connection politely and use fridge, freezer and everyday kitchen vocabulary with confidence.', '聞き取りにくい通話を丁寧に立て直し、fridge・freezerなど台所の基本語を自信を持って使います。', '3c7fb48a-4617-81e6-bede-f715c9c982be', 'https://app.notion.com/p/3c7fb48a461781e6bedef715c9c982be', 'part-1', null, 1, '{"bundled":true,"sourceSegment":"part-1","partIndex":1,"themes":["fridge / freezer","couldn’t hear","phone trouble","clarification"],"phrases":[{"en":"Please put the milk in the fridge.","jp":"牛乳を冷蔵庫に入れてください。","topic":"fridge","note":"fridge は refrigerator の日常的な短縮形です。"},{"en":"The ice cream is in the freezer.","jp":"アイスクリームは冷凍庫にあります。","topic":"freezer","note":"freezer は食品を凍らせて保存する場所です。"},{"en":"The refrigerator isn’t working.","jp":"冷蔵庫が動いていません。","topic":"appliances","note":"故障や一時的な不調には isn’t working が自然です。"},{"en":"I couldn’t hear you clearly.","jp":"あなたの声がはっきり聞こえませんでした。","topic":"couldn’t hear","note":"一時的に聞き取れなかった時の自然な言い方です。"},{"en":"I didn’t hear the doorbell.","jp":"私はドアベルの音に気づきませんでした。","topic":"didn’t hear","note":"実際にその音を聞かなかった出来事を表します。"},{"en":"I can’t hear anything.","jp":"何も聞こえません。","topic":"anything","note":"否定文では nothing ではなく anything が基本です。"},{"en":"Could you say that again?","jp":"もう一度言っていただけますか？","topic":"clarification","note":"丁寧で幅広く使える聞き返しです。"},{"en":"The connection keeps cutting out.","jp":"回線が何度も途切れます。","topic":"phone trouble","note":"cut out は音や接続が突然途切れることです。"},{"en":"You’re breaking up.","jp":"声が途切れ途切れです。","topic":"phone trouble","note":"オンライン通話で相手の声が断続的な時に使います。"},{"en":"Can you hear me now?","jp":"今は私の声が聞こえますか？","topic":"sound check","note":"接続を調整した後の確認です。"},{"en":"Let me reconnect and call you back.","jp":"接続し直して、かけ直します。","topic":"phone trouble","note":"通話を立て直す手順を自然に伝えます。"},{"en":"Could you speak a little more slowly?","jp":"もう少しゆっくり話していただけますか？","topic":"clarification","note":"速さが原因で聞き取れない時の丁寧な依頼です。"}],"draft_questions":33}'::jsonb),
  ('august-10-part-2', '2026-08-10', 'Coffee Taste & Travel Decisions — Part 2', 'コーヒーの味と旅行の決断 — Part 2', 'Compare coffee flavours and explain first-time travel plans, undecided choices and the steps that lead to booking.', 'コーヒーの風味を比べ、初めての旅行・未決定の計画・予約までの流れを説明します。', '3c7fb48a-4617-81e6-bede-f715c9c982be', 'https://app.notion.com/p/3c7fb48a461781e6bedef715c9c982be', 'part-2', null, 1, '{"bundled":true,"sourceSegment":"part-2","partIndex":2,"themes":["coffee taste","haven’t decided yet","first time","travel goals"],"phrases":[{"en":"This coffee is too strong for me.","jp":"このコーヒーは私には濃すぎます。","topic":"strong coffee","note":"strong は味や刺激が強いことを表します。"},{"en":"I prefer mild coffee.","jp":"私はまろやかなコーヒーの方が好きです。","topic":"mild coffee","note":"mild は刺激が強すぎない味です。"},{"en":"It tastes a little bitter.","jp":"少し苦い味がします。","topic":"bitter","note":"bitter は砂糖の甘さと対照的な苦味です。"},{"en":"This blend is smooth and rich.","jp":"このブレンドは口当たりがよく、コクがあります。","topic":"smooth and rich","note":"smooth は口当たり、rich は深いコクを表します。"},{"en":"I like bold coffee in the morning.","jp":"朝は力強い味のコーヒーが好きです。","topic":"bold","note":"bold ははっきりした力強い風味です。"},{"en":"This roast tastes light and slightly acidic.","jp":"この焙煎は軽くて少し酸味があります。","topic":"light and acidic","note":"light は軽い風味、acidic は酸味を表します。"},{"en":"I haven’t decided where to go yet.","jp":"まだどこへ行くか決めていません。","topic":"not decided","note":"疑問詞 + to 不定詞で選択内容を表せます。"},{"en":"It will be my first time in the Philippines.","jp":"フィリピンへ行くのは初めてになります。","topic":"first time","note":"未来の初体験には will be my first time が自然です。"},{"en":"I’ve never been to the Philippines.","jp":"私はフィリピンへ行ったことがありません。","topic":"travel experience","note":"have been to で訪問経験を表します。"},{"en":"I’d like to visit Cebu someday.","jp":"いつかセブを訪れたいです。","topic":"travel goal","note":"現実的な希望を丁寧に表します。"},{"en":"I’m still comparing the flight prices.","jp":"まだ航空券の値段を比べています。","topic":"planning","note":"still で計画途中であることを示します。"},{"en":"Once I decide, I’ll book the ticket.","jp":"決めたら、航空券を予約します。","topic":"future plan","note":"未来の条件節では once の後に現在形を使います。"}],"draft_questions":33}'::jsonb),
  ('august-16-part-1', '2026-08-16', 'Natural Collocations for Everyday Actions — Part 1', '日常動作の自然な組み合わせ — Part 1', 'Build natural everyday word partnerships for permission, household tasks, messages, transport and getting home safely.', '許可・家事・連絡・移動・帰宅の場面で、単語を自然に組み合わせるコロケーションを身につけます。', '3c7fb48a-4617-81c7-b250-e3872ff7108b', 'https://app.notion.com/p/3c7fb48a461781c7b250e3872ff7108b', 'part-1', null, 1, '{"bundled":true,"sourceSegment":"part-1","partIndex":1,"themes":["without asking","have a barbecue","do collocations","catch / receive / get"],"phrases":[{"en":"He used my computer without asking.","jp":"彼は私に断らず勝手にパソコンを使いました。","topic":"without asking","note":"「勝手に」は場面に応じて without asking で表せます。"},{"en":"She decided on her own.","jp":"彼女は自分の判断で決めました。","topic":"on your own","note":"他人に頼らず決めたことを表します。"},{"en":"Don’t just help yourself to my food.","jp":"勝手に私の食べ物を取らないでください。","topic":"help yourself","note":"許可なく取る文脈では just と否定で不満を示せます。"},{"en":"We’re having a barbecue this weekend.","jp":"今週末にバーベキューをします。","topic":"have a barbecue","note":"行事としてのBBQには have が自然です。"},{"en":"Could you do the dishes?","jp":"食器を洗ってもらえますか？","topic":"do collocations","note":"家事には do the dishes を使います。"},{"en":"I need to do some shopping.","jp":"買い物をする必要があります。","topic":"do collocations","note":"一般的な買い物活動には do some shopping が自然です。"},{"en":"She did a great job.","jp":"彼女は素晴らしい仕事をしました。","topic":"do collocations","note":"成果を褒める定番表現です。"},{"en":"I caught the last train.","jp":"私は終電に間に合いました。","topic":"catch","note":"乗り物に間に合って乗る時は catch です。"},{"en":"I caught a cold.","jp":"私は風邪をひきました。","topic":"catch","note":"病気になることを catch a cold と言います。"},{"en":"I received your email this morning.","jp":"今朝あなたのメールを受け取りました。","topic":"receive","note":"receive は少し改まった「受け取る」です。"},{"en":"I got your message.","jp":"メッセージを受け取りました。","topic":"get","note":"会話では get が自然で、「内容を理解した」の意味にもなります。"},{"en":"Did you get home safely?","jp":"無事に家に着きましたか？","topic":"get","note":"get home は「帰宅する・家に着く」です。"}],"draft_questions":33}'::jsonb),
  ('august-16-part-2', '2026-08-16', 'Change, Word Families & Weather — Part 2', '変化・語族・天気の表現 — Part 2', 'Describe personal and workplace change, connect related word forms, and distinguish hard, hardly, heavy and heavily.', '自分や職場の変化、関連する語形、hard / hardly・heavy / heavilyの使い分けを整理します。', '3c7fb48a-4617-81c7-b250-e3872ff7108b', 'https://app.notion.com/p/3c7fb48a461781c7b250e3872ff7108b', 'part-2', null, 1, '{"bundled":true,"sourceSegment":"part-2","partIndex":2,"themes":["gain / lose","word families","can’t hear","heavy rain / hardly"],"phrases":[{"en":"I’ve put on a little weight.","jp":"少し体重が増えました。","topic":"weight","note":"put on weight は日常会話で自然な表現です。"},{"en":"I’m trying to lose weight.","jp":"体重を減らそうとしています。","topic":"weight","note":"lose weight で減量を表します。"},{"en":"The company is growing quickly.","jp":"その会社は急速に成長しています。","topic":"growth","note":"組織や事業の成長には grow を使えます。"},{"en":"They increased the budget.","jp":"彼らは予算を増やしました。","topic":"budget","note":"increase は数値や量を増やすことです。"},{"en":"We need to cut the budget.","jp":"予算を削減する必要があります。","topic":"budget","note":"cut the budget は予算を減らす自然な組み合わせです。"},{"en":"It’s hard to concentrate here.","jp":"ここでは集中するのが難しいです。","topic":"concentrate","note":"concentrate は動詞、concentration は名詞です。"},{"en":"I received a certificate after the course.","jp":"講座の後に修了証を受け取りました。","topic":"certificate","note":"certificate は資格・修了を示す証明書です。"},{"en":"I’m satisfied with the result.","jp":"私は結果に満足しています。","topic":"satisfied","note":"人の気持ちは satisfied、満足させる物は satisfying です。"},{"en":"I can’t hear you over the noise.","jp":"騒音であなたの声が聞こえません。","topic":"can’t hear","note":"今この瞬間に聞こえない状況を表します。"},{"en":"It’s raining heavily.","jp":"激しく雨が降っています。","topic":"heavy rain","note":"動詞 rain は副詞 heavily で修飾します。"},{"en":"We had heavy rain last night.","jp":"昨夜は大雨でした。","topic":"heavy rain","note":"名詞 rain の前には形容詞 heavy を置きます。"},{"en":"I could hardly hear him.","jp":"彼の声がほとんど聞こえませんでした。","topic":"hardly","note":"hardly は「ほとんど〜ない」で、hard「一生懸命」と意味が違います。"}],"draft_questions":33}'::jsonb),
  ('august-17-part-1', '2026-08-17', 'Since, Headaches & Daily Habits — Part 1', 'since・頭痛・毎日の習慣 — Part 1', 'Explain how long symptoms or activities have continued and contrast used to, be used to and get used to.', '症状や活動が続く期間を伝え、used to・be used to・get used toの違いを日常の習慣で練習します。', '3c7fb48a-4617-8145-941a-c0c2fc5d9c29', 'https://app.notion.com/p/3c7fb48a46178145941ac0c2fc5d9c29', 'part-1', null, 1, '{"bundled":true,"sourceSegment":"part-1","partIndex":1,"themes":["present perfect continuous","since / for","every day / everyday","used to"],"phrases":[{"en":"I’ve had a headache since this morning.","jp":"今朝からずっと頭が痛いです。","topic":"since","note":"状態を表す have a headache は現在完了が自然です。"},{"en":"I’ve been feeling tired all day.","jp":"一日中ずっと疲れを感じています。","topic":"present perfect continuous","note":"続いている一時的な状態を強調します。"},{"en":"How long have you had the headache?","jp":"どのくらい頭痛が続いていますか？","topic":"duration","note":"How long + 現在完了で継続期間を尋ねます。"},{"en":"I’ve been studying since seven o’clock.","jp":"7時からずっと勉強しています。","topic":"since","note":"since の後には開始時点を置きます。"},{"en":"I’ve been studying for two hours.","jp":"2時間ずっと勉強しています。","topic":"for","note":"for の後には期間を置きます。"},{"en":"I walk to work every day.","jp":"私は毎日歩いて仕事へ行きます。","topic":"every day","note":"every day は「毎日」という副詞句です。"},{"en":"This is an everyday problem.","jp":"これは日常的な問題です。","topic":"everyday","note":"everyday は名詞の前で「日常の」を表す形容詞です。"},{"en":"What are you having for lunch?","jp":"昼食は何を食べますか？","topic":"lunch plans","note":"決まっている近い予定には現在進行形も自然です。"},{"en":"I’m thinking of having noodles.","jp":"麺を食べようかと考えています。","topic":"lunch plans","note":"think of + 動名詞で検討中の案を表します。"},{"en":"I used to skip breakfast.","jp":"以前は朝食を抜いていました。","topic":"used to","note":"過去の習慣で、今は違うことを示します。"},{"en":"I’m used to waking up early.","jp":"私は早起きに慣れています。","topic":"be used to","note":"be used to + 名詞・動名詞は「慣れている」です。"},{"en":"I’m getting used to the new schedule.","jp":"新しい予定にだんだん慣れてきました。","topic":"get used to","note":"変化の途中は get used to を使います。"}],"draft_questions":33}'::jsonb),
  ('august-17-part-2', '2026-08-17', 'Description, Ownership & Reactions — Part 2', '描写・持ち主・反応の表現 — Part 2', 'Describe people and belongings, ask about ownership, use entire word forms correctly, and talk about audience reactions.', '人や持ち物の描写、所有者の確認、entireの語形、期待どおりでなかった反応を自然に伝えます。', '3c7fb48a-4617-8145-941a-c0c2fc5d9c29', 'https://app.notion.com/p/3c7fb48a46178145941ac0c2fc5d9c29', 'part-2', null, 1, '{"bundled":true,"sourceSegment":"part-2","partIndex":2,"themes":["sleeveless","whose","passive voice","fall flat / go bald"],"phrases":[{"en":"She’s wearing a sleeveless shirt.","jp":"彼女はノースリーブのシャツを着ています。","topic":"clothing","note":"sleeveless は袖のない服を表します。"},{"en":"Whose bag is this?","jp":"これは誰の鞄ですか？","topic":"whose","note":"whose は持ち主を尋ねる疑問詞です。"},{"en":"Whose is this?","jp":"これは誰のものですか？","topic":"whose","note":"名詞が明らかな時は whose だけでも使えます。"},{"en":"The book was written in English.","jp":"その本は英語で書かれました。","topic":"passive voice","note":"was written は write の受動態です。"},{"en":"The entire room was silent.","jp":"部屋全体が静かでした。","topic":"entire","note":"entire は名詞を修飾する形容詞です。"},{"en":"I entirely agree with you.","jp":"私はあなたに全面的に同意します。","topic":"entirely","note":"entirely は動詞や形容詞を修飾する副詞です。"},{"en":"I read the report in its entirety.","jp":"私はレポートを最初から最後まで読みました。","topic":"entirety","note":"in its entirety は「全体を残さず」です。"},{"en":"My joke fell flat.","jp":"私の冗談は全く受けませんでした。","topic":"fall flat","note":"期待した反応が得られない時の自然な表現です。"},{"en":"The performance bombed.","jp":"その公演は大失敗でした。","topic":"bomb","note":"informal な強い表現なので使う場面に注意します。"},{"en":"He’s starting to go bald.","jp":"彼ははげ始めています。","topic":"go bald","note":"状態の変化は go + 形容詞で表せます。"},{"en":"It may rain later.","jp":"あとで雨が降るかもしれません。","topic":"may","note":"may の後は動詞の原形です。"},{"en":"That word can sound too strong.","jp":"その言葉は強すぎる印象になることがあります。","topic":"word choice","note":"意味だけでなく、相手への響きも考えて語を選びます。"}],"draft_questions":33}'::jsonb),
  ('august-23', '2026-08-23', 'Polite Work English & Suspicious Situations', '仕事の丁寧表現と「何か怪しい」', 'End a workday warmly, clarify confusing schedules and explain safely when a message, offer or situation feels suspicious.', '仕事終わりの挨拶、分かりにくい予定の確認、怪しいメッセージや状況の安全な伝え方を練習します。', '3c8fb48a-4617-817a-9095-e828b2cd2096', 'https://app.notion.com/p/3c8fb48a4617817a9095e828b2cd2096', 'full', null, 1, '{"bundled":true,"sourceSegment":"full","partIndex":0,"themes":["work greetings","open / start","confused / confusing","suspicious / fishy"],"phrases":[{"en":"Thanks for your hard work today.","jp":"今日はお疲れさまでした。","topic":"work greeting","note":"一日の仕事をねぎらう自然な英語です。"},{"en":"Thanks for taking care of that.","jp":"対応してくれてありがとうございます。","topic":"work greeting","note":"具体的な仕事への感謝を伝えます。"},{"en":"Have a good evening.","jp":"よい夜をお過ごしください。","topic":"leaving work","note":"退勤時の自然で簡潔な挨拶です。"},{"en":"What time does the store open?","jp":"その店は何時に開店しますか？","topic":"schedules","note":"決まった営業時間には現在形 does ... open を使います。"},{"en":"What time will the event start?","jp":"そのイベントは何時に始まりますか？","topic":"future event","note":"未来の一回の出来事には will も使えます。"},{"en":"I’m confused by these instructions.","jp":"この説明が分からなくて混乱しています。","topic":"confused","note":"人の気持ちは confused です。"},{"en":"These instructions are confusing.","jp":"この説明は分かりにくいです。","topic":"confusing","note":"混乱させる原因は confusing です。"},{"en":"There seems to be some confusion.","jp":"少し行き違いがあるようです。","topic":"confusion","note":"confusion は名詞で、仕事の場でも柔らかく使えます。"},{"en":"That message looks suspicious.","jp":"そのメッセージは怪しく見えます。","topic":"suspicious","note":"人・物・状況を怪しいと判断する表現です。"},{"en":"Something feels off.","jp":"何か違和感があります。","topic":"feels off","note":"断定を避けて違和感を伝える自然な表現です。"},{"en":"This deal sounds fishy.","jp":"この取引は何か怪しいです。","topic":"fishy","note":"fishy はカジュアルな「うさんくさい」です。"},{"en":"I’m a lightweight, so I don’t drink much.","jp":"お酒に弱いので、あまり飲みません。","topic":"alcohol","note":"lightweight はカジュアル。丁寧には I can’t handle much alcohol も使えます。"}],"draft_questions":33}'::jsonb),
  ('august-24', '2026-08-24', 'Dumplings, Both & Indirect Questions', '点心・both・間接疑問文', 'Describe dumplings and shared preferences, place both naturally, and turn direct questions into polite indirect questions.', '点心と共通の好みを説明し、bothの自然な位置と丁寧な間接疑問文の語順を身につけます。', '3c6fb48a-4617-804b-b367-df86ca29dba5', 'https://app.notion.com/p/3c6fb48a4617804bb367df86ca29dba5', 'full', null, 1, '{"bundled":true,"sourceSegment":"full","partIndex":0,"themes":["dumplings","both placement","must not","indirect questions"],"phrases":[{"en":"Gyoza are Japanese-style dumplings.","jp":"餃子は日本式のダンプリングです。","topic":"dumplings","note":"dumpling は皮で具を包む料理の広い呼び名です。"},{"en":"Shumai are usually steamed.","jp":"焼売は通常、蒸して作ります。","topic":"cooking","note":"be steamed は「蒸される」という調理法です。"},{"en":"These dumplings are filled with pork.","jp":"このダンプリングには豚肉が入っています。","topic":"fillings","note":"be filled with で中身を説明します。"},{"en":"We fried the gyoza until they were crispy.","jp":"餃子をカリッとするまで焼きました。","topic":"cooking","note":"until で仕上がりの状態を示します。"},{"en":"We both like gyoza.","jp":"私たちは二人とも餃子が好きです。","topic":"both placement","note":"一般動詞の前に both を置きます。"},{"en":"We are both hungry.","jp":"私たちは二人ともお腹が空いています。","topic":"both placement","note":"be動詞の後ろに both を置きます。"},{"en":"Both dishes look delicious.","jp":"どちらの料理もおいしそうです。","topic":"both placement","note":"名詞の前で both + 複数名詞を使えます。"},{"en":"He must not be at home.","jp":"彼は家にいないに違いありません。","topic":"negative deduction","note":"文脈によって must not が否定の推量を表します。"},{"en":"You must not touch this.","jp":"これに触れてはいけません。","topic":"prohibition","note":"人への指示では must not が強い禁止になります。"},{"en":"Do you know what I ate?","jp":"私が何を食べたか知っていますか？","topic":"indirect questions","note":"間接疑問では what の後を主語 + 動詞の語順にします。"},{"en":"Can you tell me where the restaurant is?","jp":"そのレストランがどこにあるか教えてもらえますか？","topic":"indirect questions","note":"where is ではなく where ... is の語順です。"},{"en":"I’m feeling under the weather today.","jp":"今日は少し体調がよくありません。","topic":"health","note":"under the weather は軽い体調不良を柔らかく表します。"}],"draft_questions":33}'::jsonb),
  ('august-25', '2026-08-25', 'Coming Home, Heading Out & Clear Pronunciation', '帰宅・外出の挨拶と発音', 'Use natural greetings for returning and leaving, then distinguish pour and poor through context and clear pronunciation.', '帰宅・外出時の自然な挨拶を使い、文脈と発音からpourとpoorをはっきり区別します。', '3c6fb48a-4617-80d4-8f16-e0d133de7fd4', 'https://app.notion.com/p/3c6fb48a461780d48f16e0d133de7fd4', 'full', null, 1, '{"bundled":true,"sourceSegment":"full","partIndex":0,"themes":["I’m home / back","welcome home / back","heading out","pour / poor"],"phrases":[{"en":"I’m home!","jp":"ただいま！","topic":"coming home","note":"自宅に帰った時の自然な一言です。"},{"en":"I’m back.","jp":"戻りました。","topic":"coming back","note":"家以外でも、元いた場所に戻った時に使えます。"},{"en":"Welcome home!","jp":"おかえりなさい！","topic":"welcome home","note":"自宅へ帰ってきた人を迎える表現です。"},{"en":"Welcome back!","jp":"お戻りなさい！","topic":"welcome back","note":"職場や授業など、戻ってきた人にも使えます。"},{"en":"I’m off.","jp":"行ってきます。","topic":"heading out","note":"出発する時の短く自然な表現です。"},{"en":"I’m heading out now.","jp":"今から出かけます。","topic":"heading out","note":"今まさに外出することを伝えます。"},{"en":"I’m heading to work.","jp":"仕事へ向かっています。","topic":"destination","note":"heading to + 場所で行き先を表します。"},{"en":"Have a good day!","jp":"よい一日を！","topic":"send-off","note":"日中に相手を送り出す定番の挨拶です。"},{"en":"Take care!","jp":"気をつけてね！","topic":"send-off","note":"安全や体調を気づかう幅広い別れの言葉です。"},{"en":"Have fun!","jp":"楽しんできてね！","topic":"send-off","note":"楽しい予定へ出かける人に使います。"},{"en":"Please pour the tea slowly.","jp":"お茶をゆっくり注いでください。","topic":"pour","note":"pour /pɔːr/ は液体を注ぐ動詞です。"},{"en":"The poor dog was left outside.","jp":"かわいそうな犬が外に置き去りにされました。","topic":"poor","note":"poor /pʊr/ または /pɔːr/ は「貧しい・かわいそうな」です。文脈で区別します。"}],"draft_questions":33}'::jsonb);
insert into public.review_lessons (
insert into review_release_020_questions values
  ('july-30-part-1', 'july-30-part-1-draft-choice-1', 0, 'Understand', 'mcq', '{"id":"july-30-part-1-draft-choice-1","format":"mcq","type":"mcq","section":"Understand","topic":"hope","isOriginal":false,"hint":"Focus on the hope meaning. Look for the sentence that expresses “来年マレーシアを訪れられるといいです。”.","hintJa":"実現可能な未来の願いには hope を使います。","explanation":"“I hope I can visit Malaysia next year.” is the sentence that means “来年マレーシアを訪れられるといいです。”. Check the complete meaning before choosing.","explanationJa":"「I hope I can visit Malaysia next year.」が「来年マレーシアを訪れられるといいです。」を表す英文です。単語一つではなく文全体の意味で選びましょう。","prompt":"Choose the English sentence that means: 来年マレーシアを訪れられるといいです。","promptJa":"「来年マレーシアを訪れられるといいです。」に合う英文を選んでください。","choices":[{"id":"a","en":"I hope I can visit Malaysia next year.","jp":"来年マレーシアを訪れられるといいです。"},{"id":"b","en":"I hope everything goes well.","jp":"すべてうまくいくといいですね。"},{"id":"c","en":"I wish I could speak English more confidently.","jp":"もっと自信を持って英語を話せたらいいのに。"},{"id":"d","en":"I wish I hadn’t said that.","jp":"あんなことを言わなければよかった。"}],"correct":"a"}'::jsonb, false, 1),
  ('july-30-part-1', 'july-30-part-1-draft-choice-2', 1, 'Understand', 'mcq', '{"id":"july-30-part-1-draft-choice-2","format":"mcq","type":"mcq","section":"Understand","topic":"hope","isOriginal":false,"hint":"Focus on the hope meaning. Look for the sentence that expresses “すべてうまくいくといいですね。”.","hintJa":"hope の後ろには現在形でも未来の意味を表せます。","explanation":"“I hope everything goes well.” is the sentence that means “すべてうまくいくといいですね。”. Check the complete meaning before choosing.","explanationJa":"「I hope everything goes well.」が「すべてうまくいくといいですね。」を表す英文です。単語一つではなく文全体の意味で選びましょう。","prompt":"Choose the English sentence that means: すべてうまくいくといいですね。","promptJa":"「すべてうまくいくといいですね。」に合う英文を選んでください。","choices":[{"id":"a","en":"I hope everything goes well.","jp":"すべてうまくいくといいですね。"},{"id":"b","en":"I wish I were in Malaysia now.","jp":"今マレーシアにいたらいいのに。"},{"id":"c","en":"I wish I had studied harder.","jp":"もっと一生懸命勉強しておけばよかった。"},{"id":"d","en":"I hope you feel better soon.","jp":"早く元気になるといいですね。"}],"correct":"a"}'::jsonb, false, 1),
  ('july-30-part-1', 'july-30-part-1-draft-choice-3', 2, 'Understand', 'mcq', '{"id":"july-30-part-1-draft-choice-3","format":"mcq","type":"mcq","section":"Understand","topic":"wish now","isOriginal":false,"hint":"Focus on the wish now meaning. Look for the sentence that expresses “今マレーシアにいたらいいのに。”.","hintJa":"今の現実と違う願いは wish + 過去形です。","explanation":"“I wish I were in Malaysia now.” is the sentence that means “今マレーシアにいたらいいのに。”. Check the complete meaning before choosing.","explanationJa":"「I wish I were in Malaysia now.」が「今マレーシアにいたらいいのに。」を表す英文です。単語一つではなく文全体の意味で選びましょう。","prompt":"Choose the English sentence that means: 今マレーシアにいたらいいのに。","promptJa":"「今マレーシアにいたらいいのに。」に合う英文を選んでください。","choices":[{"id":"a","en":"I wish I were in Malaysia now.","jp":"今マレーシアにいたらいいのに。"},{"id":"b","en":"I wish I had more free time.","jp":"もっと自由な時間があればいいのに。"},{"id":"c","en":"I wish I had gone with you.","jp":"あなたと一緒に行けばよかった。"},{"id":"d","en":"I wish the weather were cooler.","jp":"もっと涼しい天気ならいいのに。"}],"correct":"a"}'::jsonb, false, 1),
