  ('august-17-part-2', 'august-17-part-2-draft-listen-choice-2', 15, 'Listen', 'listenChoice', '{"id":"august-17-part-2-draft-listen-choice-2","format":"listenChoice","type":"listenChoice","section":"Listen","topic":"passive voice","isOriginal":false,"hint":"Focus on the passive voice meaning. Look for the sentence that expresses “その本は英語で書かれました。”.","hintJa":"was written は write の受動態です。","explanation":"The sentence in the audio is “The book was written in English.”. Listen through to the end before choosing.","explanationJa":"音声の英文は「The book was written in English.」です。最後まで聞いてから選びましょう。","prompt":"Listen and choose the sentence.","promptJa":"音声を聞いて英文を選んでください。","audioText":"The book was written in English.","choices":[{"id":"a","en":"The book was written in English.","jp":"その本は英語で書かれました。"},{"id":"b","en":"The entire room was silent.","jp":"部屋全体が静かでした。"},{"id":"c","en":"My joke fell flat.","jp":"私の冗談は全く受けませんでした。"},{"id":"d","en":"That word can sound too strong.","jp":"その言葉は強すぎる印象になることがあります。"}],"correct":"a"}'::jsonb, false, 1),
